versions.variantCss:
.wemd-callout[data-variant="bytedance-callout-left"] {
  background: var(--wemd-primary-light);
  border-radius: var(--wemd-border-radius);
  padding: 16px 20px;
  margin: 16px 0;
  border-left: 4px solid var(--wemd-primary);
}
.wemd-callout[data-variant="bytedance-callout-left"] .wemd-component-body {
  padding: 0;
}
.wemd-callout[data-variant="bytedance-callout-left"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-primary);
  font-size: 14px;
  font-weight: 700;
  margin: 0 0 6px 0;
}
.wemd-callout[data-variant="bytedance-callout-left"] .wemd-component-body .wemd-child-2 {
  color: var(--wemd-text-normal);
  font-size: 14px;
  line-height: 1.7;
  margin: 0;
}
